/**
 * Phase 23 validation: real OIDC / OAuth2 JWT authentication behind the existing token-verifier seam.
 *
 * FULLY OFFLINE AND DETERMINISTIC. A local test identity provider (an in-process loopback HTTP server) publishes an OpenID
 * configuration and a JWKS built from TEST-ONLY keys generated by this run; tokens are signed locally with those keys. The
 * backends spawned here run `AUTH_PROVIDER=oidc` against that local issuer (NODE_ENV=test, a dead AI URL, provider `test`).
 * No real identity provider, no network beyond loopback, no AI provider, no secret is used or printed.
 *
 * The verification rules under test are the PRODUCTION rules: nothing is relaxed for tests (no stub verifier is involved in the
 * OIDC servers; the stub is exercised only where a case is about refusing it).
 */
import { spawn } from "node:child_process";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { SignJWT, exportJWK, generateKeyPair } from "jose";
import { connectDatabase, disconnectDatabase } from "../src/config/database.js";
import * as Models from "../src/models/index.js";
import { Guest, Property, User, Workspace, WorkspaceMembership } from "../src/models/index.js";
import { authStartupProblems, resolveAuthConfig } from "../src/auth/authConfig.js";
import { cleanupAuthFixtures } from "./lib/authFixtures.mjs";
import { APPROVED_PROVIDER } from "../src/config/providerPolicy.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SERVER_ENTRY = path.join(__dirname, "..", "server.js");
const AUDIENCE = "eoi-api-test";
const FAKE = "6aa29b8d18df3e22b3e89cff";

let passed = 0;
let failed = 0;
const check = (name, condition, detail = "") => {
  if (condition) {
    passed += 1;
    console.log(`PASS  ${name}${detail ? ` - ${detail}` : ""}`);
  } else {
    failed += 1;
    console.error(`FAIL  ${name}${detail ? ` - ${detail}` : ""}`);
  }
};

// ------------------------------------------------------------------------------------------------ local test IdP
const b64 = (value) => Buffer.from(typeof value === "string" ? value : JSON.stringify(value)).toString("base64url");
const idp = { server: null, port: 0, issuer: "", keys: new Map(), mode: "normal", hits: { jwks: 0, discovery: 0 }, discoveryIssuer: null };
async function newKey(alg, kid) {
  const { publicKey, privateKey } = await generateKeyPair(alg, { extractable: true });
  const jwk = await exportJWK(publicKey);
  return { alg, kid, privateKey, publicJwk: { ...jwk, kid, use: "sig" } };
}
async function startIdp() {
  idp.server = http.createServer((req, res) => {
    if (req.url === "/.well-known/openid-configuration") {
      idp.hits.discovery += 1;
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify({ issuer: idp.discoveryIssuer ?? idp.issuer, jwks_uri: `${idp.issuer}/jwks` }));
    } else if (req.url === "/jwks") {
      idp.hits.jwks += 1;
      if (idp.mode === "garbage") return res.end("<html>not json</html>");
      if (idp.mode === "empty-object") return res.end(JSON.stringify({ nokeys: true }));
      if (idp.mode === "500") {
        res.statusCode = 500;
        return res.end("boom");
      }
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify({ keys: [...idp.keys.values()].map((k) => k.publicJwk) }));
    } else {
      res.statusCode = 404;
      res.end();
    }
  });
  await new Promise((resolve) => idp.server.listen(0, "127.0.0.1", resolve));
  idp.port = idp.server.address().port;
  idp.issuer = `http://127.0.0.1:${idp.port}`;
}
const nowSec = () => Math.floor(Date.now() / 1000);
/** Signs a test token. `claims` override the defaults; a claim set to `undefined` is OMITTED. */
async function sign(key, claims = {}, { alg = key.alg, kid = key.kid, typ } = {}) {
  const base = { iss: idp.issuer, aud: AUDIENCE, sub: "p23-default", iat: nowSec(), exp: nowSec() + 600 };
  const payload = { ...base, ...claims };
  for (const k of Object.keys(payload)) if (payload[k] === undefined) delete payload[k];
  return new SignJWT(payload).setProtectedHeader({ alg, kid, ...(typ ? { typ } : {}) }).sign(key.privateKey);
}

// ------------------------------------------------------------------------------------------------ servers / calls
const children = [];
function startBackend(port, env = {}, { cwd, dropEnv = [] } = {}) {
  // The stub is switched OFF by default (legacy switch and secret emptied); a case that wants it passes them explicitly.
  const merged = { ...process.env, PORT: String(port), NODE_ENV: "test", LLM_PROVIDER: "test", AI_SERVICE_URL: "http://localhost:9", KOI_RATE_LIMIT_ENABLED: "false", AUTH_PROVIDER: "oidc", AUTH_TOKEN_VERIFIER: "", AUTH_STUB_SECRET: "", OIDC_ISSUER: idp.issuer, OIDC_AUDIENCE: AUDIENCE, OIDC_JWKS_COOLDOWN_MS: "300", OIDC_JWKS_CACHE_MAX_AGE_MS: "1000", OIDC_CLOCK_TOLERANCE_SECONDS: "60", ...env };
  for (const key of dropEnv) delete merged[key];
  const child = spawn(process.execPath, [SERVER_ENTRY], { env: merged, cwd, stdio: "ignore" });
  children.push(child);
  return child;
}
const waitForPort = async (port, ms = 20000) => {
  const start = Date.now();
  for (;;) {
    try {
      if ((await fetch(`http://localhost:${port}/api/health`)).ok) return true;
    } catch {
      // not ready
    }
    if (Date.now() - start > ms) return false;
    await new Promise((resolve) => setTimeout(resolve, 200));
  }
};
const exitCode = (child, ms) => new Promise((resolve) => {
  const timer = setTimeout(() => resolve("still running"), ms);
  child.once("exit", (code) => {
    clearTimeout(timer);
    resolve(code);
  });
});
async function api(port, method, url, token, body) {
  const response = await fetch(`http://localhost:${port}/api${url}`, { method, headers: { ...(token ? { authorization: `Bearer ${token}` } : {}), ...(body !== undefined ? { "Content-Type": "application/json" } : {}) }, body: body !== undefined ? JSON.stringify(body) : undefined });
  const raw = await response.text();
  let json = null;
  try {
    json = JSON.parse(raw);
  } catch {
    json = null;
  }
  return { status: response.status, json, raw, data: json?.data, code: json?.details?.code, message: json?.message };
}
const LEAK = /jose|jwt|jws|jwk|signature|claim|kid|algorithm|audience|issuer|nbf|JWKS|RS256|ES256|HS256|stack|node_modules/i;
const ids = { workspaces: [] };

async function cleanup() {
  await connectDatabase();
  await cleanupAuthFixtures();
  const ws = { $in: ids.workspaces };
  const props = await Property.find({ workspaceId: ws }).distinct("_id");
  await Models.Unit.deleteMany({ propertyId: { $in: props } });
  await Promise.all(["Guest", "Signal", "Property", "WorkspaceMembership"].map((m) => Models[m].deleteMany({ workspaceId: ws })));
  const users = await User.find({ subject: /^p23-/ }).distinct("_id");
  await WorkspaceMembership.deleteMany({ userId: { $in: users } });
  await User.deleteMany({ _id: { $in: users } });
  await Workspace.deleteMany({ _id: ws });
  await disconnectDatabase();
}

async function main() {
  const stamp = Date.now();
  await startIdp();
  const rsa = await newKey("RS256", "kid-rsa-1");
  const ec = await newKey("ES256", "kid-ec-1");
  idp.keys.set(rsa.kid, rsa);
  idp.keys.set(ec.kid, ec);
  const rogue = await newKey("RS256", "kid-rsa-1"); // same kid as a published key, DIFFERENT key material
  const unpublished = await newKey("RS256", "kid-never-published");
  const rsa384 = await newKey("RS384", "kid-rsa-1"); // an RS384 key (alg NOT in the allow-list); never published
  const P = { main: 5141, garbage: 5142, server500: 5143, mismatch: 5144, prodNoCfg: 5145, prodOk: 5146, prodStub: 5147, unknown: 5148, prodBadAlg: 5149, testStub: 5150 };

  try {
    // ================================================ 0. configuration (pure)
    const cfg = (env, nodeEnv = "test") => {
      const backup = process.env.NODE_ENV;
      if (nodeEnv === null) delete process.env.NODE_ENV;
      else process.env.NODE_ENV = nodeEnv;
      try {
        return resolveAuthConfig(env);
      } finally {
        if (backup === undefined) delete process.env.NODE_ENV;
        else process.env.NODE_ENV = backup;
      }
    };
    const okEnv = { AUTH_PROVIDER: "oidc", OIDC_ISSUER: "https://issuer.example.com", OIDC_AUDIENCE: "api" };
    let c = cfg(okEnv, "production");
    check("CF1 a valid production OIDC configuration has no problems and yields the parsed config", c.problems.length === 0 && c.provider === "oidc" && c.oidc.issuer === "https://issuer.example.com" && c.oidc.audience[0] === "api" && c.oidc.algorithms.join() === "RS256,ES256" && c.oidc.clockToleranceSeconds === 60);
    check("CF2 production with NO authentication configuration is a problem (fail closed)", cfg({}, "production").problems.some((p) => /production requires AUTH_PROVIDER=eoi or AUTH_PROVIDER=oidc/.test(p)));
    c = cfg({ AUTH_PROVIDER: "stub", AUTH_STUB_SECRET: "x".repeat(20) }, "production");
    check("CF3 production NEVER accepts the stub verifier", c.provider === null && c.problems.length >= 1);
    check("CF3b the legacy AUTH_TOKEN_VERIFIER=stub switch is refused in production too", cfg({ AUTH_TOKEN_VERIFIER: "stub" }, "production").provider === null);
    for (const [label, mode] of [["unset NODE_ENV", null], ["an unknown NODE_ENV", "staging"]]) {
      c = cfg({ AUTH_PROVIDER: "stub" }, mode);
      check(`CF4 ${label}: the stub is refused (never falls back to the development verifier)`, c.provider === null && c.problems.some((p) => /explicit NODE_ENV/.test(p)), label);
      check(`CF4b ${label}: a valid OIDC configuration IS accepted`, cfg(okEnv, mode).oidc !== null);
      check(`CF4c ${label}: with NO provider configured nothing is selected`, cfg({}, mode).provider === null);
    }
    for (const mode of ["development", "test"]) check(`CF5 explicit ${mode}: the stub is allowed`, cfg({ AUTH_PROVIDER: "stub" }, mode).provider === "stub");
    check("CF5b explicit test: the legacy switch still selects the stub", cfg({ AUTH_TOKEN_VERIFIER: "stub" }, "test").provider === "stub");
    check("CF6 an unknown AUTH_PROVIDER value is a problem", cfg({ AUTH_PROVIDER: "saml" }).problems.length === 1);
    check("CF7 OIDC_ISSUER missing / OIDC_AUDIENCE missing are problems", cfg({ AUTH_PROVIDER: "oidc", OIDC_AUDIENCE: "a" }).oidc === null && cfg({ AUTH_PROVIDER: "oidc", OIDC_ISSUER: "https://i.example.com" }).oidc === null);
    check("CF8 http issuers are refused outside loopback-in-development/test", cfg({ ...okEnv, OIDC_ISSUER: "http://issuer.example.com" }, "test").oidc === null && cfg({ ...okEnv, OIDC_ISSUER: "http://127.0.0.1:9" }, "production").oidc === null && cfg({ ...okEnv, OIDC_ISSUER: "http://127.0.0.1:9" }, "test").oidc !== null);
    check("CF9 issuers with a query/fragment or that are not URLs are refused", cfg({ ...okEnv, OIDC_ISSUER: "https://i.example.com?x=1" }).oidc === null && cfg({ ...okEnv, OIDC_ISSUER: "not a url" }).oidc === null);
    for (const algs of ["HS256", "none", "RS256,HS512", "", "RS256,foo"]) check(`CF10 OIDC_ALGORITHMS=${JSON.stringify(algs)}: symmetric/none/unknown algorithms are refused`, algs === "" ? cfg({ ...okEnv, OIDC_ALGORITHMS: "" }).oidc !== null : cfg({ ...okEnv, OIDC_ALGORITHMS: algs }).oidc === null);
    check("CF11 out-of-range numeric settings are problems (tolerance 301, cooldown -1, timeout 5)", cfg({ ...okEnv, OIDC_CLOCK_TOLERANCE_SECONDS: "301" }).oidc === null && cfg({ ...okEnv, OIDC_JWKS_COOLDOWN_MS: "-1" }).oidc === null && cfg({ ...okEnv, OIDC_HTTP_TIMEOUT_MS: "5" }).oidc === null);
    check("CF12 audiences may be a comma-separated list; a required `typ` and a JWKS override are honoured", (() => { const x = cfg({ ...okEnv, OIDC_AUDIENCE: "a, b", OIDC_REQUIRED_TYP: "at+jwt", OIDC_JWKS_URI: "https://i.example.com/keys" }).oidc; return x.audience.join() === "a,b" && x.requiredTyp === "at+jwt" && x.jwksUri === "https://i.example.com/keys"; })());

    // ================================================ 1. servers
    await connectDatabase();
    await Promise.all([User.init(), WorkspaceMembership.init()]);
    const mkWs = async (label) => {
      const doc = await Workspace.create({ name: `P23 ${label} ${stamp}`, slug: `p23-${label}-${stamp}` });
      ids.workspaces.push(doc._id);
      return doc;
    };
    const wsA = await mkWs("a");
    const wsB = await mkWs("b");
    const A = String(wsA._id);
    const B = String(wsB._id);
    const OWN = ids.workspaces;
    const NAMES = ["Workspace", "Property", "Guest", "Stay", "Signal", "Intelligence", "KnowledgeDocument", "KnowledgeChunk", "ImportBatch", "Conversation", "Decision", "Action", "Outcome"];
    const realCounts = async () => ({
      ...Object.fromEntries(await Promise.all(NAMES.map(async (name) => [name, await Models[name].countDocuments(name === "Workspace" ? { _id: { $nin: OWN } } : { workspaceId: { $nin: OWN } })]))),
      Message: await Models.Message.countDocuments({}),
      Unit: await Models.Unit.countDocuments({ propertyId: { $nin: await Property.find({ workspaceId: { $in: OWN } }).distinct("_id") } }),
      User: await User.countDocuments({ subject: { $not: /^p23-/ } }),
      WorkspaceMembership: await WorkspaceMembership.countDocuments({ workspaceId: { $nin: OWN } }),
    });
    const before = await realCounts();

    startBackend(P.main);
    idp.mode = "normal";
    check("the OIDC backend starts (AUTH_PROVIDER=oidc against the local test issuer; the stub is disabled: AUTH_TOKEN_VERIFIER and AUTH_STUB_SECRET are emptied)", await waitForPort(P.main));

    // provisioned identities (issuer + subject), each with an explicit membership - authentication alone grants none
    const provision = async (sub, role, ws = wsA, extra = {}) => {
      const user = await User.create({ issuer: idp.issuer, subject: sub, email: `${sub}@example.invalid`, ...extra });
      if (role) await WorkspaceMembership.create({ userId: user._id, workspaceId: ws._id, role });
      return user;
    };
    const uViewer = await provision("p23-viewer", "viewer");
    const uOperator = await provision("p23-operator", "operator");
    const uReviewer = await provision("p23-reviewer", "reviewer");
    const uAdmin = await provision("p23-admin", "admin");
    const uAdminB = await provision("p23-admin-b", "admin", wsB);
    const propB = await Property.create({ workspaceId: wsB._id, name: `P23 PB ${stamp}`, code: `P23B-${stamp}` });
    const tok = (sub, claims = {}, key = rsa, opts) => sign(key, { sub, ...claims }, opts);
    const list = (token) => api(P.main, "GET", `/properties?workspaceId=${A}`, token);

    // ================================================ 2. valid authentication
    let r = await list(await tok("p23-viewer"));
    check("VA1 a valid RS256 token from the configured issuer with the configured audience authenticates (200)", r.status === 200, `HTTP ${r.status} ${r.message ?? ""}`);
    r = await list(await tok("p23-viewer", {}, ec));
    check("VA2 a valid ES256 token (a second published key type) authenticates", r.status === 200, `HTTP ${r.status}`);
    r = await list(await tok("p23-viewer", { aud: ["other-api", AUDIENCE] }));
    check("VA3 an `aud` ARRAY containing the configured audience is accepted", r.status === 200);
    r = await list(await tok("p23-viewer", { exp: nowSec() - 30 }));
    check("VA4 `exp` is enforced STRICTLY: a token that expired 30 s ago is refused (TOKEN_EXPIRED) even inside the 60 s skew that applies to nbf/iat", r.status === 401 && r.code === "TOKEN_EXPIRED", `HTTP ${r.status} ${r.code}`);
    r = await list(await tok("p23-viewer", { nbf: nowSec() + 30 }));
    check("VA5 a token whose nbf is 30 s in the future is accepted within the tolerance", r.status === 200);
    const jwksBefore = idp.hits.jwks;
    for (let i = 0; i < 30; i += 1) await list(await tok("p23-viewer"));
    check("VA6 KEYS ARE CACHED: 30 more authenticated requests caused no more than 1 extra JWKS fetch (not one per request)", idp.hits.jwks - jwksBefore <= 1, `fetches: ${idp.hits.jwks - jwksBefore}`);
    check("VA7 discovery was used once (jwks_uri came from the issuer's OpenID configuration)", idp.hits.discovery === 1, String(idp.hits.discovery));

    // ================================================ 3. invalid authentication (always 401, never a detail)
    const bad = async (label, token, expectStatus = 401, expectCode) => {
      const res = await list(token);
      check(`IA ${label}: ${expectStatus}${expectCode ? ` ${expectCode}` : ""}, no detail about what failed`, res.status === expectStatus && (!expectCode || res.code === expectCode) && !LEAK.test(res.raw.replace(/"code":"[A-Z_]+"/g, "")), `HTTP ${res.status} ${res.code ?? ""} ${res.message ?? ""}`);
      return res;
    };
    await bad("missing token", undefined, 401, "MISSING_CREDENTIAL");
    for (const [label, token] of [["not a JWT", "abc"], ["two segments", "a.b"], ["four segments", "a.b.c.d"], ["garbage segments", "x.y.z"], ["empty segments", ".."], ["oversize token", "a".repeat(9000)], ["base64 junk", `${b64("junk")}.${b64("junk")}.${b64("junk")}`]]) await bad(`malformed token (${label})`, token, 401, "INVALID_TOKEN");
    await bad("expired token", await tok("p23-viewer", { exp: nowSec() - 3600 }), 401, "TOKEN_EXPIRED");
    await bad("not-yet-valid token (nbf +1 h)", await tok("p23-viewer", { nbf: nowSec() + 3600 }), 401, "INVALID_TOKEN");
    await bad("invalid signature (a different key under a published kid)", await tok("p23-viewer", {}, rogue), 401, "INVALID_TOKEN");
    const good = await tok("p23-viewer");
    const [h, pl, sg] = good.split(".");
    await bad("tampered signature (last characters changed)", `${h}.${pl}.${sg.slice(0, -3)}AAA`, 401, "INVALID_TOKEN");
    await bad("tampered PAYLOAD (sub changed, original signature kept)", `${h}.${b64({ ...JSON.parse(Buffer.from(pl, "base64url")), sub: "p23-admin" })}.${sg}`, 401, "INVALID_TOKEN");
    await bad("tampered payload (email + role + permissions + workspaceId + groups added, original signature kept)", `${h}.${b64({ ...JSON.parse(Buffer.from(pl, "base64url")), email: "p23-admin@example.invalid", role: "admin", permissions: ["workspace:admin"], workspaceId: B, groups: ["admins"] })}.${sg}`, 401, "INVALID_TOKEN");
    await bad("wrong issuer", await tok("p23-viewer", { iss: "https://evil.example.com" }), 401, "INVALID_TOKEN");
    await bad("issuer with a trailing slash (must match EXACTLY)", await tok("p23-viewer", { iss: `${idp.issuer}/` }), 401, "INVALID_TOKEN");
    await bad("wrong audience", await tok("p23-viewer", { aud: "some-other-api" }), 401, "INVALID_TOKEN");
    await bad("audience array without the configured audience", await tok("p23-viewer", { aud: ["a", "b"] }), 401, "INVALID_TOKEN");
    await bad("missing audience", await tok("p23-viewer", { aud: undefined }), 401, "INVALID_TOKEN");
    await bad("unsupported algorithm (RS384 is not in the allow-list)", await tok("p23-viewer", {}, rsa384, { alg: "RS384" }), 401, "INVALID_TOKEN");
    const publicPem = JSON.stringify(rsa.publicJwk);
    await bad("ALGORITHM CONFUSION: HS256 signed with the PUBLIC key material as the secret", await new SignJWT({ iss: idp.issuer, aud: AUDIENCE, sub: "p23-admin", iat: nowSec(), exp: nowSec() + 600 }).setProtectedHeader({ alg: "HS256", kid: rsa.kid }).sign(new TextEncoder().encode(publicPem)), 401, "INVALID_TOKEN");
    await bad("`alg: none` (unsigned) token", `${b64({ alg: "none", typ: "JWT" })}.${b64({ iss: idp.issuer, aud: AUDIENCE, sub: "p23-admin", iat: nowSec(), exp: nowSec() + 600 })}.`, 401);
    await bad("`alg: none` with a junk signature segment", `${b64({ alg: "none" })}.${b64({ iss: idp.issuer, aud: AUDIENCE, sub: "p23-admin", exp: nowSec() + 600, iat: nowSec() })}.AAAA`, 401);
    await bad("missing `sub`", await tok(undefined, { sub: undefined }), 401, "INVALID_TOKEN");
    await bad("empty `sub`", await tok("", { sub: "" }), 401, "INVALID_TOKEN");
    await bad("missing `iss`", await tok("p23-viewer", { iss: undefined }), 401, "INVALID_TOKEN");
    await bad("missing `exp`", await tok("p23-viewer", { exp: undefined }), 401, "INVALID_TOKEN");
    await bad("missing `iat`", await tok("p23-viewer", { iat: undefined }), 401, "INVALID_TOKEN");
    await bad("`iat` far in the future", await tok("p23-viewer", { iat: nowSec() + 3600, exp: nowSec() + 7200 }), 401, "INVALID_TOKEN");
    await bad("a non-string `sub`", await tok("p23-viewer", { sub: 12345 }), 401, "INVALID_TOKEN");
    await bad("unknown `kid` (key never published)", await tok("p23-viewer", {}, unpublished), 401, "INVALID_TOKEN");
    const jwksBeforeStorm = idp.hits.jwks;
    for (let i = 0; i < 20; i += 1) await list(await tok("p23-viewer", {}, unpublished));
    check("IA-DOS 20 unknown-kid tokens in a row cause at most 2 JWKS re-fetches (the cooldown stops an attacker from making the server hammer the provider)", idp.hits.jwks - jwksBeforeStorm <= 2, `fetches: ${idp.hits.jwks - jwksBeforeStorm}`);
    check("IA-VALID a good token still works after all of that", (await list(await tok("p23-viewer"))).status === 200);

    // ================================================ 4. key rotation
    const rotated = await newKey("RS256", "kid-rsa-2");
    idp.keys.set(rotated.kid, rotated);
    await new Promise((resolve) => setTimeout(resolve, 400)); // > OIDC_JWKS_COOLDOWN_MS
    r = await list(await tok("p23-viewer", {}, rotated));
    check("KR1 ROTATION: a token signed by a NEW key (unknown kid) triggers a JWKS refresh and is accepted", r.status === 200, `HTTP ${r.status}`);
    check("KR2 ...the old key's tokens still work while the old key is published", (await list(await tok("p23-viewer"))).status === 200);
    idp.keys.delete(rsa.kid);
    await new Promise((resolve) => setTimeout(resolve, 1300)); // > cache max age
    await list(await tok("p23-viewer", {}, rotated)); // triggers the refresh cycle
    await new Promise((resolve) => setTimeout(resolve, 400));
    r = await list(await tok("p23-viewer"));
    check("KR3 a RETIRED key (removed from the JWKS) stops verifying once the cache is refreshed (401)", r.status === 401, `HTTP ${r.status}`);
    check("KR4 the new key keeps working", (await list(await tok("p23-viewer", {}, rotated))).status === 200);
    idp.keys.set(rsa.kid, rsa);

    // ================================================ 5. provider failures fail CLOSED (503, never authenticated)
    for (const [label, mode, port] of [["a garbage JWKS response", "garbage", P.garbage], ["a JWKS response without keys", "empty-object", P.server500], ["a JWKS HTTP 500", "500", P.mismatch]]) {
      idp.mode = mode;
      startBackend(port);
      await waitForPort(port);
      const res = await api(port, "GET", `/properties?workspaceId=${A}`, await tok("p23-viewer", {}, ec));
      check(`PF ${label}: verification cannot complete -> 503 AUTH_PROVIDER_UNAVAILABLE (never 200), no detail`, res.status === 503 && res.code === "AUTH_PROVIDER_UNAVAILABLE" && !LEAK.test(res.raw.replace(/"code":"[A-Z_]+"/g, "")), `HTTP ${res.status} ${res.code}`);
    }
    idp.mode = "normal";
    idp.discoveryIssuer = "https://not-the-configured-issuer.example.com";
    startBackend(P.prodBadAlg);
    await waitForPort(P.prodBadAlg);
    r = await api(P.prodBadAlg, "GET", `/properties?workspaceId=${A}`, await tok("p23-viewer", {}, ec));
    check("PF discovery document naming ANOTHER issuer is not trusted (503)", r.status === 503 && r.code === "AUTH_PROVIDER_UNAVAILABLE", `HTTP ${r.status}`);
    idp.discoveryIssuer = null;
    r = await api(P.garbage, "GET", `/properties?workspaceId=${A}`);
    check("PF no token is still a plain 401 when the provider is broken", r.status === 401);

    // ================================================ 6. identity mapping
    const usersBefore = await User.countDocuments({});
    const stranger = await tok("p23-first-login", { email: "p23-first-login@example.invalid" });
    r = await list(stranger);
    check("ID1 FIRST LOGIN of an unknown identity: authenticated but NOT provisioned -> 403 IDENTITY_NOT_REGISTERED", r.status === 403 && r.code === "IDENTITY_NOT_REGISTERED", `HTTP ${r.status} ${r.code}`);
    for (let i = 0; i < 5; i += 1) await list(stranger);
    check("ID2 repeated logins of an unknown identity create NO User (no auto-provisioning) and NO membership", (await User.countDocuments({})) === usersBefore && !(await User.findOne({ subject: "p23-first-login" })));
    // the operator provisions the identity (User only, no membership yet)
    const newUser = await provision("p23-first-login", null);
    r = await list(stranger);
    check("ID3 once provisioned WITHOUT a membership, the identity authenticates but gets NO workspace access (404): authentication never implies authorization", r.status === 404, `HTTP ${r.status}`);
    r = await api(P.main, "GET", `/workspaces`, stranger);
    check("ID3b ...and its workspace list is empty; it was NOT made a member or an admin of anything", r.status === 200 && r.data.length === 0 && (await WorkspaceMembership.countDocuments({ userId: newUser._id })) === 0);
    const usersMid = await User.countDocuments({});
    for (let i = 0; i < 5; i += 1) await list(await tok("p23-viewer"));
    check("ID4 REPEATED logins of a provisioned identity resolve the SAME User and create no duplicates", (await User.countDocuments({})) === usersMid && (await User.countDocuments({ issuer: idp.issuer, subject: "p23-viewer" })) === 1);
    // issuer + sub is the identity: same `sub` under a DIFFERENT issuer is a different user
    const other = await User.create({ issuer: "https://other-issuer.example.com", subject: "p23-viewer", email: "other@example.invalid" });
    await WorkspaceMembership.create({ userId: other._id, workspaceId: wsA._id, role: "admin" });
    r = await api(P.main, "POST", "/properties", await tok("p23-viewer"), { workspaceId: A, name: "x", code: "x" });
    check("ID5 the same `sub` under ANOTHER issuer is a different User: the configured issuer's viewer is NOT the other issuer's admin (403)", r.status === 403, `HTTP ${r.status}`);
    // email is only an attribute
    r = await list(await tok("p23-viewer", { email: "p23-admin@example.invalid" }));
    r = await api(P.main, "POST", "/properties", await tok("p23-viewer", { email: "p23-admin@example.invalid" }), { workspaceId: A, name: "x", code: "x" });
    check("ID6 EMAIL DOES NOT IDENTIFY: a token for subject `p23-viewer` carrying the ADMIN's email is still the viewer (403)", r.status === 403);
    r = await list(await tok("p23-viewer", { email: "brand-new-address@example.invalid" }));
    check("ID7 an email CHANGE does not change identity (same User, 200) and the stored email is NOT rewritten from the token", r.status === 200 && (await User.findOne({ issuer: idp.issuer, subject: "p23-viewer" })).email === "p23-viewer@example.invalid");
    r = await list(await tok("p23-viewer", { email: undefined }));
    check("ID8 a token WITHOUT an email authenticates normally", r.status === 200);
    r = await list(await tok("p23-viewer", { email: "p23-first-login@example.invalid" }));
    check("ID9 a token carrying ANOTHER user's email does not act as that user (still the viewer's own access)", r.status === 200);
    await User.updateOne({ _id: uViewer._id }, { $set: { status: "disabled" } });
    r = await list(await tok("p23-viewer"));
    check("ID10 a DISABLED user with a perfectly valid token -> 403 USER_DISABLED", r.status === 403 && r.code === "USER_DISABLED");
    await User.updateOne({ _id: uViewer._id }, { $set: { status: "active" } });
    await WorkspaceMembership.updateOne({ userId: uViewer._id, workspaceId: wsA._id }, { $set: { status: "revoked" } });
    r = await list(await tok("p23-viewer"));
    check("ID11 a REVOKED membership: authenticated, but 404 (no workspace access)", r.status === 404);
    await WorkspaceMembership.updateOne({ userId: uViewer._id, workspaceId: wsA._id }, { $set: { status: "active" } });
    check("ID12 the operator can re-enable and the same token works again", (await list(await tok("p23-viewer"))).status === 200);
    check("ID13 `groups`, `roles`, `role`, `permissions`, `scope`, `workspaceId` and `knowledge level` claims in a VALID token are IGNORED (the viewer stays a viewer)", await (async () => {
      const t = await tok("p23-viewer", { groups: ["admins", "eoi-admin"], roles: ["admin"], role: "admin", permissions: ["workspace:admin", "action:execute"], scope: "workspace:admin", workspaceId: B, knowledgeLevel: "restricted", email_verified: true, preferred_username: "p23-admin", name: "Admin" });
      const write = await api(P.main, "POST", "/properties", t, { workspaceId: A, name: "x", code: "x" });
      const foreign = await api(P.main, "GET", `/properties?workspaceId=${B}`, t);
      const guests = await api(P.main, "GET", `/guests?workspaceId=${A}`, t);
      return write.status === 403 && foreign.status === 404 && guests.status === 403;
    })());

    // ================================================ 7. authorization regression with OIDC identities
    const T = { viewer: await tok("p23-viewer"), operator: await tok("p23-operator"), reviewer: await tok("p23-reviewer"), admin: await tok("p23-admin"), adminB: await tok("p23-admin-b") };
    const expect = async (label, method, url, who, status, body) => {
      const res = await api(P.main, method, url, T[who], body);
      check(`AZ ${who}: ${label} -> ${status}`, res.status === status, `HTTP ${res.status} ${res.message ?? ""}`);
      return res;
    };
    for (const who of ["viewer", "operator", "reviewer", "admin"]) await expect("read properties (intelligence:view)", "GET", `/properties?workspaceId=${A}`, who, 200);
    await expect("read guests (operations:view)", "GET", `/guests?workspaceId=${A}`, "viewer", 403);
    for (const who of ["operator", "reviewer", "admin"]) await expect("read guests", "GET", `/guests?workspaceId=${A}`, who, 200);
    await expect("create a property (workspace:admin)", "POST", "/properties", "operator", 403, { workspaceId: A, name: "x", code: "x1" });
    await expect("create a property", "POST", "/properties", "reviewer", 403, { workspaceId: A, name: "x", code: "x2" });
    const created = await expect("create a property", "POST", "/properties", "admin", 201, { workspaceId: A, name: `P23 prop ${stamp}`, code: `P23-${stamp}` });
    await expect("create a guest (operations:manage)", "POST", "/guests", "viewer", 403, { workspaceId: A, firstName: "x", lastName: "y" });
    const guest = await expect("create a guest", "POST", "/guests", "operator", 201, { workspaceId: A, firstName: "P23", lastName: "Guest" });
    await expect("delete a guest (workspace:admin)", "DELETE", `/guests/${guest.data?._id}?workspaceId=${A}`, "operator", 403);
    await expect("delete a guest", "DELETE", `/guests/${guest.data?._id}?workspaceId=${A}`, "admin", 200);
    await expect("decision review permission absent for operator (legacy PATCH)", "PATCH", `/decisions/${FAKE}?workspaceId=${A}`, "operator", 403, { status: "approved" });
    await expect("Action writes are denied to EVERY role (action:execute is held by nobody)", "POST", "/actions", "admin", 403, { workspaceId: A, intelligenceId: FAKE, description: "x" });
    await expect("learning is admin-only", "GET", `/learning?workspaceId=${A}`, "reviewer", 403);
    await expect("...and admin may read it", "GET", `/learning?workspaceId=${A}`, "admin", 200);
    await expect("workspace admin route: PATCH status is refused for admin (Phase 22)", "PATCH", `/workspaces/${A}`, "admin", 409, { status: "suspended" });
    await expect("workspace PATCH by an operator", "PATCH", `/workspaces/${A}`, "operator", 403, { name: "x" });
    await expect("CROSS-WORKSPACE: an admin of A reading workspace B", "GET", `/properties?workspaceId=${B}`, "admin", 404);
    await expect("CROSS-WORKSPACE: admin of B reading workspace A", "GET", `/properties?workspaceId=${A}`, "adminB", 404);
    await expect("OBJECT-LEVEL: B's property under workspace A", "GET", `/properties/${propB._id}?workspaceId=${A}`, "admin", 404);
    await expect("OBJECT-LEVEL: B's property via workspace B by A's admin", "GET", `/properties/${propB._id}?workspaceId=${B}`, "admin", 404);
    await expect("OBJECT-LEVEL: B's admin can read B's property", "GET", `/properties/${propB._id}?workspaceId=${B}`, "adminB", 200);
    await expect("a stray body/query workspace does not override membership", "POST", `/properties?workspaceId=${A}`, "admin", 404, { workspaceId: B, name: "x", code: "y" });
    r = await api(P.main, "GET", `/workspaces`, T.admin);
    check("AZ the workspace list contains only the identity's own workspace", r.status === 200 && r.data.length === 1 && r.data[0]._id === A);
    r = await api(P.main, "GET", `/properties?workspaceId=${A}`, T.viewer);
    check("AZ responses carry no token, claim or identity internals", !/"(issuer|subject|sub|iss|aud|email|role|permissions?)"/i.test(r.raw));
    void created;

    // ================================================ 8. environment / startup behavior
    startBackend(P.prodNoCfg, { NODE_ENV: "production", AUTH_PROVIDER: "", OIDC_ISSUER: "", OIDC_AUDIENCE: "" });
    check("EV1 PRODUCTION with NO authentication configuration REFUSES TO START (exit 1)", (await exitCode(children.at(-1), 15000)) === 1);
    startBackend(P.prodBadAlg + 100, { NODE_ENV: "production", OIDC_ISSUER: "https://127.0.0.1:9", OIDC_ALGORITHMS: "HS256" });
    check("EV2 PRODUCTION with an unsafe algorithm list (HS256) REFUSES TO START", (await exitCode(children.at(-1), 15000)) === 1);
    startBackend(P.prodBadAlg + 101, { NODE_ENV: "production", OIDC_ISSUER: "http://issuer.example.com" });
    check("EV3 PRODUCTION with an http issuer REFUSES TO START", (await exitCode(children.at(-1), 15000)) === 1);
    startBackend(P.prodBadAlg + 102, { NODE_ENV: "production", OIDC_AUDIENCE: "" });
    check("EV4 PRODUCTION with no audience REFUSES TO START", (await exitCode(children.at(-1), 15000)) === 1);
    startBackend(P.prodStub, { NODE_ENV: "production", AUTH_PROVIDER: "stub", AUTH_STUB_SECRET: "x".repeat(24) });
    check("EV5 PRODUCTION with AUTH_PROVIDER=stub REFUSES TO START (the stub can never run in production)", (await exitCode(children.at(-1), 15000)) === 1);
    startBackend(P.prodOk, { NODE_ENV: "production", LLM_PROVIDER: APPROVED_PROVIDER, OIDC_ISSUER: "https://127.0.0.1:9", OIDC_AUDIENCE: AUDIENCE });
    check("EV6 PRODUCTION with a valid OIDC configuration starts", await waitForPort(P.prodOk));
    r = await api(P.prodOk, "GET", `/properties?workspaceId=${A}`, await tok("p23-viewer"));
    check("EV7 ...and with an unreachable issuer it fails CLOSED (503, never authenticated) even for a token signed by a key we hold", r.status === 503 && r.code === "AUTH_PROVIDER_UNAVAILABLE", `HTTP ${r.status} ${r.code}`);
    // a stub-signed token (what the development tooling issues) is never accepted by the OIDC verifier
    const { signStubToken, STUB_ISSUER } = await import("../src/auth/stubTokenVerifier.js");
    const stubToken = signStubToken({ iss: STUB_ISSUER, sub: "p23-admin", exp: nowSec() + 600 }, "eoi-suite-stub-secret-not-real-0123456789");
    r = await list(stubToken);
    check("EV8 a development STUB token is REJECTED by the OIDC server (401)", r.status === 401, `HTTP ${r.status}`);
    startBackend(P.unknown, { LLM_PROVIDER: APPROVED_PROVIDER, AUTH_PROVIDER: "stub", AUTH_STUB_SECRET: "eoi-suite-stub-secret-not-real-0123456789", NODE_ENV: "" }, { cwd: os.tmpdir(), dropEnv: ["NODE_ENV"] });
    check("EV9 an UNSET NODE_ENV with AUTH_PROVIDER=stub starts, but the stub is REFUSED (authenticated requests -> 503 AUTH_NOT_CONFIGURED)", (await waitForPort(P.unknown)) && (await api(P.unknown, "GET", `/properties?workspaceId=${A}`, stubToken)).status === 503);
    startBackend(P.testStub, { AUTH_PROVIDER: "stub", AUTH_STUB_SECRET: "eoi-suite-stub-secret-not-real-0123456789" });
    await waitForPort(P.testStub);
    r = await api(P.testStub, "GET", `/properties?workspaceId=${A}`, signStubToken({ iss: STUB_ISSUER, sub: "p23-admin", exp: nowSec() + 600 }, "eoi-suite-stub-secret-not-real-0123456789"));
    check("EV10 explicit NODE_ENV=test + AUTH_PROVIDER=stub: the stub verifier works (deterministic test authentication is preserved), but that stub user is unregistered (403)", r.status === 403 && r.code === "IDENTITY_NOT_REGISTERED", `HTTP ${r.status}`);
    r = await api(P.testStub, "GET", `/properties?workspaceId=${A}`, await tok("p23-viewer"));
    check("EV11 ...and a real-OIDC-style token is NOT accepted by the stub server (401)", r.status === 401);

    // ================================================ 8b. operator provisioning tool
    const { spawnSync } = await import("node:child_process");
    const provisionTool = (...args) => spawnSync(process.execPath, [path.join(__dirname, "provision-user.mjs"), ...args], { encoding: "utf8", env: { ...process.env, NODE_ENV: "test" }, timeout: 60000 });
    let pv = provisionTool("--issuer", idp.issuer, "--subject", "p23-cli-user", "--email", "cli@example.invalid", "--workspace", `p23-a-${stamp}`, "--role", "operator");
    check("PV1 the provisioning tool creates the User and the membership (exit 0)", pv.status === 0 && /user created/.test(pv.stdout) && /membership created/.test(pv.stdout), pv.stderr.slice(0, 120));
    pv = provisionTool("--issuer", idp.issuer, "--subject", "p23-cli-user", "--workspace", `p23-a-${stamp}`, "--role", "operator");
    check("PV2 it is IDEMPOTENT: a second run changes nothing and creates no duplicate", pv.status === 0 && /nothing changed/.test(pv.stdout) && (await User.countDocuments({ issuer: idp.issuer, subject: "p23-cli-user" })) === 1 && (await WorkspaceMembership.countDocuments({ workspaceId: wsA._id, userId: (await User.findOne({ subject: "p23-cli-user" }))._id })) === 1);
    pv = provisionTool("--issuer", idp.issuer, "--subject", "p23-cli-user", "--workspace", `p23-a-${stamp}`, "--role", "admin");
    check("PV3 changing an existing membership's role is REFUSED without --update-role (never a silent escalation)", pv.status === 1 && /--update-role/.test(pv.stderr) && (await WorkspaceMembership.findOne({ userId: (await User.findOne({ subject: "p23-cli-user" }))._id })).role === "operator");
    check("PV4 --workspace without --role is refused (no role is ever assumed) and --role without --workspace too", provisionTool("--issuer", idp.issuer, "--subject", "p23-cli-2", "--workspace", `p23-a-${stamp}`).status === 1 && provisionTool("--issuer", idp.issuer, "--subject", "p23-cli-2", "--role", "admin").status === 1 && !(await User.findOne({ subject: "p23-cli-2" })));
    r = await api(P.main, "GET", `/guests?workspaceId=${A}`, await tok("p23-cli-user"));
    check("PV5 the provisioned identity can now sign in with exactly its role (operator: guests readable)", r.status === 200);
    check("PV6 a User-only provisioning (no workspace) grants no access", provisionTool("--issuer", idp.issuer, "--subject", "p23-cli-3").status === 0 && (await api(P.main, "GET", `/properties?workspaceId=${A}`, await tok("p23-cli-3"))).status === 404);

    // ================================================ 9. integrity
    const after = await realCounts();
    const drift = Object.keys(before).filter((k) => before[k] !== after[k]);
    check("DB1: every PRE-EXISTING record count is identical", drift.length === 0, drift.map((k) => `${k}:${before[k]}->${after[k]}`).join(","));
    check("OFF1: the whole suite ran against a LOOPBACK issuer only (no external identity provider, no AI provider)", idp.issuer.startsWith("http://127.0.0.1:"));
    void Guest;
  } finally {
    for (const c of children) c.kill();
    idp.server?.close();
    await Promise.all(children.map((c) => (c.exitCode === null && c.signalCode === null ? new Promise((resolve) => c.once("exit", resolve)) : Promise.resolve())));
    try {
      await cleanup();
      check("mongodb cleanup", true);
    } catch (error) {
      check("mongodb cleanup", false, String(error));
    }
  }
}

main()
  .then(() => {
    console.log(`\nPhase 23 OIDC validation: ${passed} passed, ${failed} failed`);
    process.exit(failed === 0 ? 0 : 1);
  })
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
